+
+        Locator aboutLink = page.locator("text=About");
+        aboutLink.click();
+
+        Locator keepEditing = page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Keep editing"));
+        keepEditing.waitFor();
+        keepEditing.click();
+        keepEditing.waitFor(new Locator.WaitForOptions().setState(WaitForSelectorState.HIDDEN));
+
+        assertEquals("Unsaved Person", name.getValue());
+        assertEquals("Contact", page.locator("h1").innerText());
+    }
+
+    @Test
+    void discardProceedsToAboutView() {
+        TextFieldElement name = TextFieldElement.getByLabel(page, "Name");
+        name.setValue("Unsaved Person");
+
+        Locator aboutLink = page.locator("text=About");
+        aboutLink.click();
+
+        Locator discard = page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Discard"));
+        discard.waitFor();
+        discard.click();
+
+        page.locator("h1").getByText("About").waitFor();
+    }
+
+    @Test
