+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    @Test
+    void headingAndAboutLinkPresent() {
+        navigate(ContactView.class);
+        H1 heading = find(H1.class).single();
+        assertEquals("Contact", heading.getText());
+
+        RouterLink about = find(RouterLink.class).single();
+        assertEquals("About", about.getText());
+    }
+
+    @Test
+    void aboutViewHasHeading() {
+        navigate(AboutView.class);
+        H1 heading = find(H1.class).single();
+        assertEquals("About", heading.getText());
+    }
+
+    @Test
+    void emptyFormHasSendEnabled() {
+        navigate(ContactView.class);
+        Button send = findSend();
+        assertTrue(send.isEnabled());
+    }
+
+    @Test
+    void blankNameIsRejected() {
+        navigate(ContactView.class);
+        fill("", "a@b.com", "", "hello");
+        clickSend();
+
+        TextField name = find(TextField.class).withLabel("Name").single();
+        assertTrue(name.isInvalid());
+        assertEquals("Name is required", name.getErrorMessage());
+        assertNoMessageSent();
+    }
+
+    @Test
+    void invalidEmailIsRejected() {
+        navigate(ContactView.class);
+        fill("Jane", "not-an-email", "", "hello");
+        clickSend();
+
+        EmailField email = find(EmailField.class).single();
+        assertTrue(email.isInvalid());
+        assertEquals("Enter a valid e-mail address", email.getErrorMessage());
+        assertNoMessageSent();
+    }
+
+    @Test
+    void missingEmailAndPhoneIsRejected() {
+        navigate(ContactView.class);
+        fill("Jane", "", "", "hello");
+        clickSend();
+
+        EmailField email = find(EmailField.class).single();
+        assertTrue(email.isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email.getErrorMessage());
+        assertNoMessageSent();
+    }
+
+    @Test
+    void phoneAloneIsEnough() {
+        navigate(ContactView.class);
+        fill("Jane", "", "555-1234", "hello there");
+        clickSend();
+
+        EmailField email = find(EmailField.class).single();
+        assertFalse(email.isInvalid());
+        assertMessageSent();
+    }
+
+    @Test
+    void blankMessageIsRejected() {
+        navigate(ContactView.class);
+        fill("Jane", "a@b.com", "", "");
+        clickSend();
+
+        TextArea message = find(TextArea.class).single();
+        assertTrue(message.isInvalid());
+        assertEquals("Message is required", message.getErrorMessage());
+        assertNoMessageSent();
+    }
+
+    @Test
+    void tooLongMessageIsRejected() {
+        navigate(ContactView.class);
+        fill("Jane", "a@b.com", "", "x".repeat(501));
+        clickSend();
+
+        TextArea message = find(TextArea.class).single();
+        assertTrue(message.isInvalid());
+        assertEquals("Message must be at most 500 characters", message.getErrorMessage());
+        assertNoMessageSent();
+    }
+
+    @Test
+    void successfulSendClearsFormAndNotifiesAndDisablesSend() {
+        navigate(ContactView.class);
+        fill("Jane Doe", "jane@example.com", "", "Hello there");
+        clickSend();
+
+        assertMessageSent();
+
+        TextField name = find(TextField.class).withLabel("Name").single();
+        EmailField email = find(EmailField.class).single();
+        TextField phone = find(TextField.class).withLabel("Phone").single();
+        TextArea message = find(TextArea.class).single();
+        assertEquals("", name.getValue());
+        assertEquals("", email.getValue());
+        assertEquals("", phone.getValue());
+        assertEquals("", message.getValue());
+
+        Button send = findSend();
+        assertFalse(send.isEnabled());
+
+        Grid<ContactMessage> grid = (Grid<ContactMessage>) (Grid) find(Grid.class).single();
+        GridTester<Grid<ContactMessage>, ContactMessage> gridTester = test(grid);
+        assertTrue(gridTester.size() >= 1);
+        assertEquals("Jane Doe", gridTester.getRow(0).name());
+
+        test(TextFieldTester.class, name).setValue("A");
+        assertTrue(send.isEnabled());
+    }
+
+    @Test
+    void enterKeySendsWhenValid() {
+        navigate(ContactView.class);
+        fill("Jane Doe", "jane@example.com", "", "Hello there");
+        fireShortcut(Key.ENTER);
+
+        assertMessageSent();
+    }
+
+    @Test
+    void newestMessageIsFirstAndSurvivesRenavigation() {
+        navigate(ContactView.class);
+        Grid<ContactMessage> initialGrid = (Grid<ContactMessage>) (Grid) find(Grid.class).single();
+        int sizeBefore = test(initialGrid).size();
+
+        fill("First Person", "first@example.com", "", "first message");
+        clickSend();
+
+        fill("Second Person", "second@example.com", "", "second message");
+        clickSend();
+
+        Grid<ContactMessage> grid = (Grid<ContactMessage>) (Grid) find(Grid.class).single();
+        GridTester<Grid<ContactMessage>, ContactMessage> gridTester = test(grid);
+        assertEquals(sizeBefore + 2, gridTester.size());
+        assertEquals("Second Person", gridTester.getRow(0).name());
+        assertEquals("First Person", gridTester.getRow(1).name());
+
+        navigate(AboutView.class);
+        navigate(ContactView.class);
+
+        Grid<ContactMessage> grid2 = (Grid<ContactMessage>) (Grid) find(Grid.class).single();
+        GridTester<Grid<ContactMessage>, ContactMessage> gridTester2 = test(grid2);
+        assertEquals(sizeBefore + 2, gridTester2.size());
+    }
+
+    @Test
+    void navigatingAwayWithDirtyFormAsksFirstAndKeepEditingStays() {
+        navigate(ContactView.class);
+        fill("Jane", "", "", "");
+
+        RouterLink about = find(RouterLink.class).single();
+        test(about).navigate();
+
+        Dialog dialog = find(Dialog.class).single();
+        Button keepEditing = find(Button.class, dialog).withText("Keep editing").single();
+        test(ButtonTester.class, keepEditing).click();
+
+        assertTrue(getCurrentView() instanceof ContactView);
+        TextField name = find(TextField.class).withLabel("Name").single();
+        assertEquals("Jane", name.getValue());
+    }
+
+    @Test
+    void navigatingAwayWithDirtyFormDiscardProceeds() {
+        navigate(ContactView.class);
+        fill("Jane", "", "", "");
+
+        RouterLink about = find(RouterLink.class).single();
+        test(about).navigate();
+
+        Dialog dialog = find(Dialog.class).single();
+        Button discard = find(Button.class, dialog).withText("Discard").single();
+        test(ButtonTester.class, discard).click();
+
+        assertTrue(getCurrentView() instanceof AboutView);
+    }
+
+    @Test
+    void navigatingAwayWithCleanFormDoesNotAsk() {
+        navigate(ContactView.class);
+
+        RouterLink about = find(RouterLink.class).single();
