+
+        assertFalse(find(Dialog.class).exists());
+        assertTrue(getCurrentView() instanceof AboutView);
+    }
+
+    private void fill(String name, String email, String phone, String message) {
+        test(TextFieldTester.class, find(TextField.class).withLabel("Name").single()).setValue(name);
+        test(TextFieldTester.class, find(EmailField.class).single()).setValue(email);
