+
+    private void clickSend() {
+        test(ButtonTester.class, findSend()).click();
+    }
+
+    private Button findSend() {
+        return find(Button.class).withText("Send").single();
+    }
+
+    private void assertMessageSent() {
+        Notification notification = find(Notification.class).single();
+        NotificationTester<Notification> tester = test(notification);
+        assertTrue(tester.getText().contains("Message sent"));
